clear
clc

% Infinite-dimensional space-time Fourier proof for the Neumann KS orbit.
% INTLAB is used for the residual and for every final scalar inequality.
% The finite inverse and exhaustive interface scan are regenerated by
% scan_block_proof.py; no Newton correction is made in this driver.
script_directory = fileparts(mfilename('fullpath'));
output_directory = fullfile(script_directory,'outputs');
if ~isempty(getenv('KS_CAP_OUTPUT_DIR'))
    output_directory = getenv('KS_CAP_OUTPUT_DIR');
end
candidate_file = fullfile(output_directory,'ks_neumann_cap_candidate.mat');
proof_data_file = fullfile(output_directory,'ks_neumann_fourier_proof_data.mat');
if ~exist(candidate_file,'file')
    error('Missing high-resolution candidate: %s',candidate_file)
end
if ~exist(proof_data_file,'file')
    error(['Missing Fourier proof data. Run scan_block_proof.py --output ', ...
        'outputs/ks_neumann_fourier_proof_data.mat first.'])
end
candidate = load(candidate_file);
proof = load(proof_data_file);
if ~isfield(proof,'source_frequency') || ...
        proof.source_frequency ~= candidate.frequency || ...
        proof.source_interval_length ~= candidate.interval_length
    error('Proof data do not match this candidate; regenerate the scan.')
end
projected_candidate = candidate.velocity_time_fourier;
candidate_M = (size(projected_candidate,1)-1)/2;
for n=-candidate_M:candidate_M
    for k=1:size(projected_candidate,2)
        if mod(n+k,2) ~= 0
            projected_candidate(n+candidate_M+1,k)=0;
        end
    end
end
projected_candidate(candidate_M+1,:) = real(projected_candidate(candidate_M+1,:));
projected_candidate(1:candidate_M,:) = conj(flipud(projected_candidate(candidate_M+2:end,:)));
if ~isequal(projected_candidate,proof.projected_velocity_time_fourier)
    error('Proof data contain coefficients from a different candidate.')
end
if strcmp(getenv('KS_REQUIRE_SURROGATE'),'1')
    if ~isfield(candidate,'candidate_origin') || ...
            ~strcmp(candidate.candidate_origin,'data_fitted_surrogate_only') || ...
            ~isfield(candidate,'true_system_optimizer_calls') || ...
            candidate.true_system_optimizer_calls ~= 0
        error('A surrogate-only candidate with zero true-system solves is required.')
    end
end
if candidate.newton_corrections ~= 0
    error('The proof driver accepts only a zero-transfer-correction candidate.')
end

M = double(proof.temporal_modes);
K = double(proof.spatial_modes);
Mt = double(proof.candidate_temporal_modes);
Kx = double(proof.candidate_spatial_modes);
dimension = double(proof.dimension);
if M ~= 160 || K ~= 40 || Mt ~= 160 || Kx ~= 60
    error('This certificate was audited for (M,K;Mt,Kx)=(160,40;160,60).')
end
if candidate.interval_length ~= 22
    error('This proof is implemented for interval length 22.')
end

% Treat all stored IEEE coefficients and the finite inverse as exact dyadic
% data. INTLAB encloses their norms with outward rounding.
iB = intval(proof.finite_inverse);
iBnorm = norm(iB,1);
iAnorm_mid = intval(proof.finite_operator_norm_1);

% Absolute majorants for the floating-point audit (see PROOF_AUDIT.md).
% Bounds use magnitudes BEFORE cancellation, not the norm of the assembled
% matrix as a surrogate for construction error.
iu = intval(2)^(-53);
gamma_matrix = dimension*iu/(1-dimension*iu);
gamma_column = intval(2^20)*iu/(1-intval(2^20)*iu);
iell = intval(22);
iq = intval('pi')/iell;
inu = iq^2;
iomega = intval(double(candidate.frequency));
ifrequency = iomega/inu;
Cphysical = proof.projected_velocity_time_fourier;
Ureal = intval(zeros(2*Mt+1,Kx));
Ureal(1,:) = intval(real(Cphysical(Mt+1,:)))/iq;
Ureal(2:Mt+1,:) = 2*intval(real(Cphysical(Mt+2:end,:)))/iq;
Ureal(Mt+2:end,:) = -2*intval(imag(Cphysical(Mt+2:end,:)))/iq;
iUnorm = sum(abs(Ureal),'all');
iHarmonics = intval([0,1:Mt,1:Mt]');
iTangentNorm = sum(iHarmonics.*abs(Ureal),'all');
factor = (1+sqrt(intval(2)))/2;
% The global shifted symbol has p >= 3/(4*nu). Raw symbols at integer
% spatial modes are separated from zero. Beyond k=2100 both quantities
% below decrease, so the finite maximum also covers all larger modes.
ks = intval(1:2100);
raw_p = inu*ks.^4-ks.^2;
symbol_condition = max((inu*ks.^4+ks.^2)./abs(raw_p));
if sup(symbol_condition) > 4096 || inf(ifrequency) <= 0
    error('Symbol conditioning exceeds the forward-error audit budget.')
end
ismooth = factor*4*inu/3;
iraw_dx = max(factor*ks./abs(raw_p));
% Absolute column sums of every intermediate in the finite operator.
iAmajorant = 1 + ismooth/inu + ismooth*K*iUnorm + ...
    2*iTangentNorm + ismooth*iTangentNorm;
operator_build_guard = 8*gamma_column*iAmajorant;
iAnorm = iAnorm_mid/(1-gamma_matrix);
matrix_product_guard = gamma_matrix*iBnorm*iAnorm;
subtraction_guard = iu*(1+iBnorm*iAnorm);
finite_defect = intval(proof.finite_defect_mid)/(1-gamma_matrix) + ...
    matrix_product_guard + subtraction_guard + iBnorm*operator_build_guard;
% Tail-to-core products have at most K spatial derivative multipliers.
% The raw tail majorant covers every temporal input (including n=0).
core_column_guard = 8*gamma_column*ismooth*K*iUnorm;
raw_column_guard = 8*gamma_column*iraw_dx*iUnorm;
interface_guard = iBnorm*core_column_guard + raw_column_guard + ...
    8*(gamma_column+gamma_matrix)* ...
    (1+intval(proof.maximum_coarse_tail_column_mid));
% Include the frequency-to-tail column explicitly, as well as state columns.
frequency_tail_guard = 8*gamma_column*factor/ifrequency*iUnorm;
finite_input_bound = finite_defect + max( ...
    intval(proof.maximum_finite_to_tail_mid)+raw_column_guard, ...
    intval(proof.frequency_to_tail_mid)+frequency_tail_guard);
tail_interface_bound = max(intval(proof.refine_threshold), ...
    intval(proof.maximum_refined_tail_column_mid)) + interface_guard;
tail_far_bound = max([intval(proof.maximum_temporal_gap_mid), ...
    intval(proof.maximum_temporal_far_mid), ...
    intval(proof.maximum_spatial_far_mid)]) + raw_column_guard + ...
    8*gamma_column*(1+iraw_dx*iUnorm);
alpha_interval = max([finite_input_bound,tail_interface_bound,tail_far_bound]);
alpha = sup(alpha_interval);

% Recompute the de-aliased residual of the exactly symmetry-projected
% polynomial using interval trigonometric evaluation. There are 641 phase
% nodes, sufficient for the degree-320 temporal quadratic, and 120 spatial
% output modes, sufficient for the degree-60 sine polynomial squared.
output_t = 2*Mt;
output_x = 2*Kx;
node_count = 2*output_t+1;
itheta = 2*intval('pi')*intval((0:node_count-1)')/node_count;
harmonics = 1:Mt;
iEval = [intval(ones(node_count,1)), cos(itheta*harmonics), ...
    sin(itheta*harmonics)];
iValues = iEval*Ureal;
iNonlinearValues = intval(zeros(node_count,output_x));
for j = 1:Kx
    for k = 1:Kx
        product = iValues(:,j).*iValues(:,k);
        difference = abs(j-k);
        if difference > 0
            iNonlinearValues(:,difference) = ...
                iNonlinearValues(:,difference)-intval(0.25*difference)*product;
        end
        total = j+k;
        iNonlinearValues(:,total) = ...
            iNonlinearValues(:,total)+intval(0.25*total)*product;
    end
end
iProject = [intval(ones(1,node_count))/node_count; ...
    2*cos(itheta*intval(1:output_t))'/node_count; ...
    2*sin(itheta*intval(1:output_t))'/node_count];
iResidual = iProject*iNonlinearValues;

spatial_modes = intval(1:Kx);
ilambda = inu*spatial_modes.^4-spatial_modes.^2;
iResidual(1,1:Kx) = iResidual(1,1:Kx)+ilambda.*Ureal(1,:);
for n = 1:Mt
    cosine_row = n+1;
    sine_row = output_t+n+1;
    input_sine_row = Mt+n+1;
    iResidual(cosine_row,1:Kx) = iResidual(cosine_row,1:Kx)+ ...
        ifrequency*n*Ureal(input_sine_row,:)+ilambda.*Ureal(cosine_row,:);
    iResidual(sine_row,1:Kx) = iResidual(sine_row,1:Kx)- ...
        ifrequency*n*Ureal(cosine_row,:)+ilambda.*Ureal(input_sine_row,:);
end

iSmoothedResidual = apply_inverse(iResidual,ifrequency,inu,true);
iRawResidual = apply_inverse(iResidual,ifrequency,inu,false);
finite_mask = false(size(iResidual));
for n = 0:M
    for k = 1:K
        if mod(n+k,2) == 0
            finite_mask(n+1,k) = true;
            if n > 0
                finite_mask(output_t+n+1,k) = true;
            end
        end
    end
end
finite_smoothed_l1 = sum(abs(iSmoothedResidual(finite_mask)));
tail_raw_l1 = sum(abs(iRawResidual(~finite_mask)));
Y_interval = iBnorm*finite_smoothed_l1+tail_raw_l1;
Y = sup(Y_interval);

% The finite matrix products defining the quadratic coefficient were
% regenerated in double precision. gamma_n encloses both their dot products
% and column sums; the same construction guard covers q and frequency.
quadratic_guard = 8*(gamma_column+2*gamma_matrix)* ...
    (1+iBnorm*ismooth*(M+K/2)+factor/ifrequency+iraw_dx/2);
Z2_interval = intval(proof.quadratic_bound_mid)+quadratic_guard;
Z2 = sup(Z2_interval);

discriminant_interval = (1-alpha_interval)^2-4*Y_interval*Z2_interval;
discriminant = inf(discriminant_interval);
if alpha < 1 && discriminant > 0
    radius_lower_interval = ((1-alpha_interval)- ...
        sqrt(discriminant_interval))/(2*Z2_interval);
    radius_upper_interval = ((1-alpha_interval)+ ...
        sqrt(discriminant_interval))/(2*Z2_interval);
    radius_lower = sup(radius_lower_interval);
    radius_upper = inf(radius_upper_interval);
    validation_radius = intval('1e-5');
    radius_polynomial = Z2_interval*validation_radius^2- ...
        (1-alpha_interval)*validation_radius+Y_interval;
    contraction_bound = sup(alpha_interval+2*Z2_interval*validation_radius);
    finite_galerkin_proof_success = true;
    tail_bound_complete = true;
    pde_proof_success = radius_lower > 0 && radius_lower < radius_upper && ...
        inf(validation_radius) > radius_lower && ...
        sup(validation_radius) < radius_upper && sup(radius_polynomial) < 0 && ...
        contraction_bound < 1;
else
    radius_lower = NaN;
    radius_upper = NaN;
    validation_radius = intval(NaN);
    radius_polynomial = intval(NaN);
    contraction_bound = Inf;
    finite_galerkin_proof_success = alpha < 1;
    tail_bound_complete = true;
    pde_proof_success = false;
end
newton_corrections = 0;
true_frequency = inu*(ifrequency+midrad(0,sup(validation_radius)));
if inf(true_frequency) <= 0
    error('Validated frequency interval must be positive.')
end
true_period = 2*intval('pi')/true_frequency;
time_dependent_coefficient_lower = ...
    max(inf(abs(Ureal(2:end,:))),[],'all')-sup(validation_radius);
pde_proof_success = pde_proof_success && ...
    time_dependent_coefficient_lower > 0;

fprintf('Neumann KS ordinary orbit: T = %.16g, omega = %.16g\n', ...
    double(candidate.period),double(candidate.frequency))
fprintf('Symmetry-reduced finite block: dimension = %d, (M,K)=(%d,%d)\n', ...
    dimension,M,K)
fprintf('CAP transfer Newton corrections: %d\n',newton_corrections)
fprintf('PDE radii data: Y <= %.16e, alpha <= %.16e, Z2 <= %.16e\n', ...
    Y,alpha,Z2)
fprintf('Discriminant >= %.16e, radius in [%.16e, %.16e]\n', ...
    discriminant,radius_lower,radius_upper)
fprintf('Chosen radius = %.16e, radii polynomial <= %.16e\n', ...
    sup(validation_radius),sup(radius_polynomial))
fprintf('True period enclosure = [%.16g, %.16g]\n', ...
    inf(true_period),sup(true_period))
fprintf('finite_galerkin_proof_success=%d\n',finite_galerkin_proof_success)
fprintf('tail_bound_complete=%d\n',tail_bound_complete)
fprintf('pde_proof_success=%d\n',pde_proof_success)

summary = table(finite_galerkin_proof_success,tail_bound_complete, ...
    pde_proof_success,newton_corrections,M,K,dimension,Y,alpha,Z2, ...
    discriminant,radius_lower,radius_upper,sup(finite_input_bound), ...
    sup(tail_interface_bound),sup(tail_far_bound), ...
    sup(validation_radius),sup(radius_polynomial),inf(true_period), ...
    sup(true_period),time_dependent_coefficient_lower, ...
    double(candidate.period),double(candidate.frequency), ...
    'VariableNames',{'finite_galerkin_proof_success','tail_bound_complete', ...
    'pde_proof_success','newton_corrections','temporal_modes', ...
    'spatial_modes','finite_dimension','Y','alpha','Z2','discriminant', ...
    'radius_lower','radius_upper','finite_input_bound', ...
    'tail_interface_bound','tail_far_bound','validation_radius', ...
    'radius_polynomial','true_period_lower','true_period_upper', ...
    'time_dependent_coefficient_lower','candidate_period', ...
    'candidate_frequency'});
writetable(summary,fullfile(output_directory,'ks_neumann_cap_summary.csv'))

certificate = struct;
certificate.formulation = 'Neumann potential / odd velocity';
certificate.orbit_type = 'ordinary periodic';
certificate.period = double(candidate.period);
certificate.frequency = double(candidate.frequency);
certificate.temporal_modes = M;
certificate.spatial_modes = K;
certificate.finite_dimension = dimension;
certificate.Y = Y;
certificate.alpha = alpha;
certificate.Z2 = Z2;
certificate.discriminant = discriminant;
certificate.radius_lower = radius_lower;
certificate.radius_upper = radius_upper;
certificate.validation_radius = sup(validation_radius);
certificate.radius_polynomial = sup(radius_polynomial);
certificate.contraction_bound = contraction_bound;
certificate.true_period_lower = inf(true_period);
certificate.true_period_upper = sup(true_period);
certificate.time_dependent_coefficient_lower = ...
    time_dependent_coefficient_lower;
certificate.newton_corrections = newton_corrections;
if isfield(candidate,'candidate_origin')
    certificate.candidate_origin = candidate.candidate_origin;
    certificate.true_system_optimizer_calls = candidate.true_system_optimizer_calls;
else
    certificate.candidate_origin = 'legacy_true_Galerkin_refinement';
end
certificate.finite_galerkin_proof_success = finite_galerkin_proof_success;
certificate.tail_bound_complete = tail_bound_complete;
certificate.pde_proof_success = pde_proof_success;
fid = fopen(fullfile(output_directory,'ks_neumann_full_pde_certificate.json'),'w');
fprintf(fid,'%s',jsonencode(certificate,PrettyPrint=true));
fclose(fid);
if ~pde_proof_success
    error('Infinite-dimensional validation failed; see certificate bounds.')
end

function result = apply_inverse(coefficients,frequency,nu,shifted)
    temporal_modes = (size(coefficients,1)-1)/2;
    spatial = intval(1:size(coefficients,2));
    p = nu*spatial.^4-spatial.^2;
    if shifted
        p = p+1/nu;
    end
    result = intval(zeros(size(coefficients)));
    result(1,:) = coefficients(1,:)./p;
    for n = 1:temporal_modes
        z = frequency*n;
        denominator = p.^2+z.^2;
        cosine = coefficients(n+1,:);
        sine = coefficients(temporal_modes+n+1,:);
        result(n+1,:) = (p.*cosine-z.*sine)./denominator;
        result(temporal_modes+n+1,:) = ...
            (z.*cosine+p.*sine)./denominator;
    end
end
